const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat, HeadingLevel,
  BorderStyle, WidthType, ShadingType, VerticalAlign, PageNumber,
  PageBreak, TabStopType, TabStopPosition
} = require("docx");

// Brand palette (premium, understated)
const INK = "26242B";        // near-black charcoal for body
const DARK = "2B2730";       // header block
const ACCENT = "A6885F";     // warm taupe gold
const ACCENT_DK = "8A6F4C";
const CREAM = "F4EEE6";      // soft fill for table headers
const GREY = "6E6A73";       // guidance / muted text
const RULE = "D8CFC2";       // light divider

const CONTENT_W = 9360;

const border = (color = RULE, size = 1) => ({ style: BorderStyle.SINGLE, size, color });
const cellBorders = { top: border(), bottom: border(), left: border(), right: border() };
const cellMargins = { top: 90, bottom: 90, left: 140, right: 140 };

// guidance text run (italic, muted) - tells Bethany what to put in each section
const guide = (text) => new Paragraph({
  spacing: { before: 40, after: 160 },
  children: [new TextRun({ text, italics: true, color: GREY, size: 19 })]
});

const body = (text, opts = {}) => new Paragraph({
  spacing: { before: 0, after: 120, line: 276 },
  children: [new TextRun({ text, color: INK, size: 21, ...opts })]
});

const placeholder = (text) => new Paragraph({
  spacing: { before: 0, after: 140, line: 276 },
  children: [new TextRun({ text, color: "9A9099", size: 21, italics: true })]
});

// metadata table row
const metaRow = (label, value) => new TableRow({
  children: [
    new TableCell({
      borders: cellBorders, margins: cellMargins, width: { size: 2700, type: WidthType.DXA },
      shading: { fill: CREAM, type: ShadingType.CLEAR },
      verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({ children: [new TextRun({ text: label, bold: true, color: INK, size: 19 })] })]
    }),
    new TableCell({
      borders: cellBorders, margins: cellMargins, width: { size: 6660, type: WidthType.DXA },
      verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({ children: [new TextRun({ text: value, color: GREY, size: 19, italics: true })] })]
    })
  ]
});

// section heading with accent rule underneath
const section = (num, title) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 300, after: 120 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: ACCENT, space: 4 } },
  children: [
    new TextRun({ text: `${num}.  `, bold: true, color: ACCENT_DK, size: 24 }),
    new TextRun({ text: title, bold: true, color: DARK, size: 24 })
  ]
});

const subhead = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 180, after: 80 },
  children: [new TextRun({ text, bold: true, color: ACCENT_DK, size: 21 })]
});

const bullet = (text, level = 0) => new Paragraph({
  numbering: { reference: "bullets", level },
  spacing: { after: 80, line: 276 },
  children: [new TextRun({ text, color: INK, size: 21 })]
});

const numbered = (text) => new Paragraph({
  numbering: { reference: "steps", level: 0 },
  spacing: { after: 100, line: 276 },
  children: [new TextRun({ text, color: INK, size: 21 })]
});

// roles & responsibilities table
const roleHeaderRow = new TableRow({
  tableHeader: true,
  children: ["Role", "Responsibility in this procedure"].map((t, i) => new TableCell({
    borders: cellBorders, margins: cellMargins,
    width: { size: i === 0 ? 3000 : 6360, type: WidthType.DXA },
    shading: { fill: DARK, type: ShadingType.CLEAR },
    children: [new Paragraph({ children: [new TextRun({ text: t, bold: true, color: "FFFFFF", size: 19 })] })]
  }))
});
const roleRow = (role, resp) => new TableRow({
  children: [
    new TableCell({ borders: cellBorders, margins: cellMargins, width: { size: 3000, type: WidthType.DXA },
      children: [new Paragraph({ children: [new TextRun({ text: role, bold: true, color: INK, size: 19 })] })] }),
    new TableCell({ borders: cellBorders, margins: cellMargins, width: { size: 6360, type: WidthType.DXA },
      children: [new Paragraph({ children: [new TextRun({ text: resp, color: GREY, size: 19, italics: true })] })] })
  ]
});

// revision history table
const revHeaderRow = new TableRow({
  tableHeader: true,
  children: ["Version", "Date", "Author", "Summary of change"].map((t, i) => new TableCell({
    borders: cellBorders, margins: cellMargins,
    width: { size: [1400, 1800, 2200, 3960][i], type: WidthType.DXA },
    shading: { fill: DARK, type: ShadingType.CLEAR },
    children: [new Paragraph({ children: [new TextRun({ text: t, bold: true, color: "FFFFFF", size: 19 })] })]
  }))
});
const revRow = (v, d, a, s) => new TableRow({
  children: [v, d, a, s].map((t, i) => new TableCell({
    borders: cellBorders, margins: cellMargins,
    width: { size: [1400, 1800, 2200, 3960][i], type: WidthType.DXA },
    children: [new Paragraph({ children: [new TextRun({ text: t, color: i === 0 ? INK : GREY, size: 18, italics: i !== 0 })] })]
  }))
});

const doc = new Document({
  creator: "The Luxora Collective",
  title: "Standard Operating Procedure Template",
  styles: {
    default: { document: { run: { font: "Calibri", size: 21, color: INK } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Calibri", color: DARK },
        paragraph: { spacing: { before: 300, after: 120 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 21, bold: true, font: "Calibri", color: ACCENT_DK },
        paragraph: { spacing: { before: 180, after: 80 }, outlineLevel: 1 } },
    ]
  },
  numbering: {
    config: [
      { reference: "bullets", levels: [
        { level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { run: { color: ACCENT_DK }, paragraph: { indent: { left: 540, hanging: 260 } } } },
        { level: 1, format: LevelFormat.BULLET, text: "\u2013", alignment: AlignmentType.LEFT,
          style: { run: { color: ACCENT_DK }, paragraph: { indent: { left: 1020, hanging: 260 } } } }
      ]},
      { reference: "steps", levels: [
        { level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { run: { bold: true, color: ACCENT_DK }, paragraph: { indent: { left: 540, hanging: 360 } } } }
      ]}
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1260, right: 1440, bottom: 1260, left: 1440 }
      }
    },
    headers: {
      default: new Header({ children: [new Paragraph({
        spacing: { after: 0 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 6 } },
        tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
        children: [
          new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, color: DARK, size: 16, characterSpacing: 30 }),
          new TextRun({ text: "\tStandard Operating Procedure", color: GREY, size: 16, italics: true })
        ]
      })] })
    },
    footers: {
      default: new Footer({ children: [new Paragraph({
        spacing: { before: 0 },
        border: { top: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 6 } },
        tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
        children: [
          new TextRun({ text: "theluxoracollective.co", color: GREY, size: 16 }),
          new TextRun({ text: "\tConfidential  |  Page ", color: GREY, size: 16 }),
          new TextRun({ children: [PageNumber.CURRENT], color: GREY, size: 16 }),
          new TextRun({ text: " of ", color: GREY, size: 16 }),
          new TextRun({ children: [PageNumber.TOTAL_PAGES], color: GREY, size: 16 })
        ]
      })] })
    },
    children: [
      // ---------- Title block ----------
      new Paragraph({
        spacing: { before: 80, after: 20 },
        children: [new TextRun({ text: "STANDARD OPERATING PROCEDURE", bold: true, color: ACCENT_DK, size: 20, characterSpacing: 40 })]
      }),
      new Paragraph({
        spacing: { after: 60 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: ACCENT, space: 6 } },
        children: [new TextRun({ text: "[SOP Title]", bold: true, color: DARK, size: 40 })]
      }),
      guide("Replace the title above with the procedure name. Keep it action based, for example Closer Onboarding, Client Kickoff Setup, or Revenue Leak Audit Delivery."),

      // ---------- Metadata table ----------
      new Paragraph({ spacing: { before: 80, after: 100 }, children: [] }),
      new Table({
        width: { size: CONTENT_W, type: WidthType.DXA },
        columnWidths: [2700, 6660],
        rows: [
          metaRow("SOP Number", "[TLC-SOP-000]"),
          metaRow("Department / Function", "[Sales / Delivery / Operations / Marketing]"),
          metaRow("Process Owner", "[Name and role accountable for this SOP]"),
          metaRow("Version", "[1.0]"),
          metaRow("Effective Date", "[Month Day, Year]"),
          metaRow("Last Reviewed", "[Month Day, Year]"),
          metaRow("Next Review Due", "[Month Day, Year, reviewed at least every 6 months]"),
          metaRow("Approved By", "[Name, role, date]")
        ]
      }),

      // ---------- 1. Purpose ----------
      section("1", "Purpose"),
      guide("State in one or two sentences why this procedure exists and the outcome it protects. Lead with the result, not the task."),
      placeholder("This procedure exists to [outcome]. It ensures that [standard or result] is delivered consistently every time, regardless of who performs the work."),

      // ---------- 2. Scope ----------
      section("2", "Scope"),
      guide("Define exactly what this SOP covers and, just as important, what it does not. Name the situations or stages where it applies."),
      subhead("This procedure applies to"),
      placeholder("[The role, team, or stage this governs, for example all commissioned closers during the first 14 days of onboarding.]"),
      subhead("This procedure does not cover"),
      placeholder("[Adjacent work handled by a different SOP, with a reference to that SOP where helpful.]"),

      // ---------- 3. Roles and Responsibilities ----------
      section("3", "Roles and Responsibilities"),
      guide("List every role that touches this procedure and the single responsibility each one owns. Keep responsibilities to one clear sentence."),
      new Table({
        width: { size: CONTENT_W, type: WidthType.DXA },
        columnWidths: [3000, 6360],
        rows: [
          roleHeaderRow,
          roleRow("[Process Owner]", "[Accountable for the SOP staying current and being followed.]"),
          roleRow("[Performer]", "[Carries out the steps in the procedure.]"),
          roleRow("[Reviewer / Approver]", "[Signs off on the output or the SOP itself.]")
        ]
      }),

      // ---------- 4. Definitions and Tools ----------
      section("4", "Definitions, Systems, and Access Required"),
      guide("List the terms, platforms, logins, templates, and assets a person needs before starting. This removes guesswork and prevents delays mid process."),
      subhead("Key terms"),
      bullet("[Term]: [plain language definition]"),
      subhead("Systems and tools"),
      bullet("[CRM, scheduler, drive folder, template, or login required]"),
      subhead("Inputs required before starting"),
      bullet("[Documents, data, approvals, or assets that must be in hand]"),

      // ---------- 5. Procedure ----------
      section("5", "Procedure"),
      guide("The core of the SOP. Write each step as a single instruction starting with a verb. A new person should be able to follow it without asking a question. Group long procedures into the phases below and delete any phase you do not need."),

      subhead("Phase A: [Name the phase]"),
      numbered("[Action, written as a clear instruction. Note who does it if more than one role is involved.]"),
      numbered("[Next action. Include the exact system, field, or template where relevant.]"),
      numbered("[Next action.]"),

      subhead("Phase B: [Name the phase]"),
      numbered("[Action.]"),
      numbered("[Action. Reference any script, checklist, or template by name.]"),
      numbered("[Action.]"),

      subhead("Phase C: [Name the phase]"),
      numbered("[Action.]"),
      numbered("[Final action that completes the procedure and confirms the handoff or close.]"),

      // ---------- 6. Quality Standards ----------
      section("6", "Quality Standards and Definition of Done"),
      guide("Describe what good looks like so the result can be judged objectively. This is how the Process Owner verifies the work was done to standard."),
      subhead("This procedure is complete when"),
      bullet("[Observable, checkable outcome, for example the record is updated and the next step is scheduled.]"),
      bullet("[Second outcome.]"),
      subhead("Quality standards to uphold"),
      bullet("[Brand, tone, accuracy, or timing standard that must be met.]"),

      // ---------- 7. Common Pitfalls ----------
      section("7", "Common Pitfalls and Troubleshooting"),
      guide("Capture the mistakes people actually make and how to avoid or fix them. This section grows over time as the team learns."),
      bullet("Pitfall: [what tends to go wrong]. Fix: [how to prevent or correct it]."),
      bullet("Pitfall: [what tends to go wrong]. Fix: [how to prevent or correct it]."),

      // ---------- 8. Related Documents ----------
      section("8", "Related Documents and References"),
      guide("Link the playbooks, scripts, agreements, and other SOPs this procedure connects to, so the reader can navigate the system."),
      bullet("[Related SOP, playbook, or template name and location]"),
      bullet("[Related SOP, playbook, or template name and location]"),

      // ---------- 9. Revision History ----------
      section("9", "Revision History"),
      guide("Record every meaningful change. Update the version number here and in the metadata table at the same time."),
      new Table({
        width: { size: CONTENT_W, type: WidthType.DXA },
        columnWidths: [1400, 1800, 2200, 3960],
        rows: [
          revHeaderRow,
          revRow("1.0", "[Date]", "[Author]", "[Initial release]"),
          revRow("[1.1]", "[Date]", "[Author]", "[What changed and why]")
        ]
      }),

      new Paragraph({ spacing: { before: 240 },
        border: { top: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 6 } },
        children: [new TextRun({ text: "Owned and maintained by The Luxora Collective. Do not distribute outside the team without approval from the Process Owner.", italics: true, color: GREY, size: 17 })] })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/TLC_SOP_Template.docx", buffer);
  console.log("written");
});

