const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, LevelFormat, HeadingLevel,
  BorderStyle, WidthType, ShadingType, VerticalAlign, PageNumber,
  TabStopType, TabStopPosition
} = require("docx");

const INK = "26242B", DARK = "2B2730", ACCENT = "A6885F", ACCENT_DK = "8A6F4C";
const CREAM = "F4EEE6", GREY = "6E6A73", RULE = "D8CFC2";
const CONTENT_W = 9360;

const border = (color = RULE, size = 1) => ({ style: BorderStyle.SINGLE, size, color });
const cellBorders = { top: border(), bottom: border(), left: border(), right: border() };
const cellMargins = { top: 90, bottom: 90, left: 140, right: 140 };

const body = (text) => new Paragraph({ spacing: { after: 120, line: 276 },
  children: [new TextRun({ text, color: INK, size: 21 })] });

const section = (num, title) => new Paragraph({
  heading: HeadingLevel.HEADING_1, spacing: { before: 280, after: 120 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: ACCENT, space: 4 } },
  children: [
    new TextRun({ text: `${num}.  `, bold: true, color: ACCENT_DK, size: 24 }),
    new TextRun({ text: title, bold: true, color: DARK, size: 24 })
  ]
});

const bullet = (text) => new Paragraph({ numbering: { reference: "b", level: 0 },
  spacing: { after: 80, line: 276 }, children: [new TextRun({ text, color: INK, size: 21 })] });

const hcell = (t, w) => new TableCell({ borders: cellBorders, margins: cellMargins,
  width: { size: w, type: WidthType.DXA }, shading: { fill: DARK, type: ShadingType.CLEAR },
  children: [new Paragraph({ children: [new TextRun({ text: t, bold: true, color: "FFFFFF", size: 19 })] })] });
const cell = (t, w, opts = {}) => new TableCell({ borders: cellBorders, margins: cellMargins,
  width: { size: w, type: WidthType.DXA }, shading: opts.fill ? { fill: opts.fill, type: ShadingType.CLEAR } : undefined,
  children: [new Paragraph({ children: [new TextRun({ text: t, color: opts.color || INK, size: 19, bold: opts.bold, italics: opts.italics })] })] });

const doc = new Document({
  creator: "The Luxora Collective",
  title: "SOP Standards",
  styles: {
    default: { document: { run: { font: "Calibri", size: 21, color: INK } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Calibri", color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 0 } }
    ]
  },
  numbering: { config: [
    { reference: "b", levels: [{ level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
      style: { run: { color: ACCENT_DK }, paragraph: { indent: { left: 540, hanging: 260 } } } }] }
  ]},
  sections: [{
    properties: { page: { size: { width: 12240, height: 15840 },
      margin: { top: 1260, right: 1440, bottom: 1260, left: 1440 } } },
    headers: { default: new Header({ children: [new Paragraph({ spacing: { after: 0 },
      border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 6 } },
      tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
      children: [
        new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, color: DARK, size: 16, characterSpacing: 30 }),
        new TextRun({ text: "\tSOP Standards", color: GREY, size: 16, italics: true })
      ] })] }) },
    footers: { default: new Footer({ children: [new Paragraph({ spacing: { before: 0 },
      border: { top: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 6 } },
      tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
      children: [
        new TextRun({ text: "theluxoracollective.co", color: GREY, size: 16 }),
        new TextRun({ text: "\tConfidential  |  Page ", color: GREY, size: 16 }),
        new TextRun({ children: [PageNumber.CURRENT], color: GREY, size: 16 }),
        new TextRun({ text: " of ", color: GREY, size: 16 }),
        new TextRun({ children: [PageNumber.TOTAL_PAGES], color: GREY, size: 16 })
      ] })] }) },
    children: [
      new Paragraph({ spacing: { before: 80, after: 20 },
        children: [new TextRun({ text: "OPERATING STANDARDS", bold: true, color: ACCENT_DK, size: 20, characterSpacing: 40 })] }),
      new Paragraph({ spacing: { after: 60 },
        border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: ACCENT, space: 6 } },
        children: [new TextRun({ text: "SOP Standards", bold: true, color: DARK, size: 40 })] }),
      new Paragraph({ spacing: { before: 120, after: 80 },
        children: [new TextRun({ text: "This is the front sheet for the Luxora SOP library. It defines how every standard operating procedure is named, written, owned, reviewed, and stored. Read it before creating or editing any SOP. The rules here keep the library consistent as it grows.", color: GREY, size: 21, italics: true })] }),

      // 1. Numbering
      section("1", "Numbering Convention"),
      body("Every SOP carries a unique identifier in this format:"),
      new Paragraph({ spacing: { before: 40, after: 140 }, alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "TLC-SOP-[FUNCTION]-[###]", bold: true, color: ACCENT_DK, size: 28 })] }),
      body("The function code groups the SOP by the part of the business it serves. The three digit number runs in sequence within that function, starting at 001."),
      new Table({ width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: [1700, 7660],
        rows: [
          new TableRow({ tableHeader: true, children: [hcell("Code", 1700), hcell("Function", 7660)] }),
          new TableRow({ children: [cell("SAL", 1700, { bold: true, fill: CREAM }), cell("Sales: setting, closing, pipeline, and sales call analysis", 7660, { color: GREY }) ] }),
          new TableRow({ children: [cell("DEL", 1700, { bold: true, fill: CREAM }), cell("Client Delivery: Revenue Leak Audit, Market Blueprint, and Growth Engine execution", 7660, { color: GREY }) ] }),
          new TableRow({ children: [cell("MKT", 1700, { bold: true, fill: CREAM }), cell("Marketing: ads, content, outreach, and partner campaigns", 7660, { color: GREY }) ] }),
          new TableRow({ children: [cell("REC", 1700, { bold: true, fill: CREAM }), cell("Recruiting and Hiring: sourcing, hiring briefs, and onboarding", 7660, { color: GREY }) ] }),
          new TableRow({ children: [cell("OPS", 1700, { bold: true, fill: CREAM }), cell("Operations: internal systems, coordination, and administration", 7660, { color: GREY }) ] }),
          new TableRow({ children: [cell("FIN", 1700, { bold: true, fill: CREAM }), cell("Finance: billing, reporting, and financial planning", 7660, { color: GREY }) ] })
        ]
      }),
      new Paragraph({ spacing: { before: 120, after: 60 }, children: [new TextRun({ text: "Rules", bold: true, color: ACCENT_DK, size: 21 })] }),
      bullet("Numbers are assigned in the master SOP index, never chosen independently."),
      bullet("Numbers are never reused. A retired SOP keeps its number permanently."),
      bullet("Example: the second Sales SOP created is TLC-SOP-SAL-002."),

      // 2. Document standards
      section("2", "Document Standards"),
      bullet("Every SOP is built from the standard Luxora SOP template and keeps all nine sections in order."),
      bullet("File name matches the SOP number and title, for example TLC-SOP-SAL-001 Closer Onboarding."),
      bullet("Brand voice applies throughout: no em dashes anywhere, formal full words rather than contractions, no corporate filler."),
      bullet("Steps are written as single instructions that begin with a verb, so a new person can follow them without asking a question."),

      // 3. Ownership
      section("3", "Ownership and Approval"),
      bullet("Each SOP has one named Process Owner who is accountable for keeping it accurate and followed."),
      bullet("The Process Owner drafts and edits. The function lead, or the CEO where the function lead is the owner, gives final approval before an SOP goes Active."),
      bullet("Only the Process Owner, or someone they delegate, edits a live SOP. All other input goes through them."),

      // 4. Review
      section("4", "Review and Versioning"),
      bullet("Every SOP is reviewed at least once every six months. The next review date is set in the metadata table and tracked in the master index."),
      bullet("Minor wording or formatting changes increase the version by one decimal, for example 1.0 to 1.1."),
      bullet("A change that alters the actual procedure increases the whole number, for example 1.4 to 2.0."),
      bullet("Every change is recorded in the Revision History table inside the SOP and the version is updated in the master index at the same time."),

      // 5. Storage
      section("5", "Where SOPs Live"),
      bullet("All SOPs live in one source of truth: the Luxora SOP library folder. No working copies are kept elsewhere."),
      bullet("The master SOP index is the single register of every SOP, its number, owner, status, and review date."),
      bullet("A new SOP is not considered Active until it is approved, numbered in the index, and saved to the library folder."),

      // 6. Lifecycle
      section("6", "Lifecycle and Status"),
      body("Every SOP sits in one of four states, tracked in the master index:"),
      new Table({ width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: [1900, 7460],
        rows: [
          new TableRow({ tableHeader: true, children: [hcell("Status", 1900), hcell("Meaning", 7460)] }),
          new TableRow({ children: [cell("Draft", 1900, { bold: true, fill: CREAM }), cell("Being written. Not yet approved and not in use.", 7460, { color: GREY }) ] }),
          new TableRow({ children: [cell("In Review", 1900, { bold: true, fill: CREAM }), cell("Complete and awaiting approval from the function lead or CEO.", 7460, { color: GREY }) ] }),
          new TableRow({ children: [cell("Active", 1900, { bold: true, fill: CREAM }), cell("Approved and in force. This is the version the team follows.", 7460, { color: GREY }) ] }),
          new TableRow({ children: [cell("Retired", 1900, { bold: true, fill: CREAM }), cell("Replaced or no longer used. Kept for record. Its number is not reused.", 7460, { color: GREY }) ] })
        ]
      }),
      new Paragraph({ spacing: { before: 280 },
        border: { top: { style: BorderStyle.SINGLE, size: 4, color: RULE, space: 6 } },
        children: [new TextRun({ text: "Owned and maintained by The Luxora Collective. These standards govern every document in the SOP library.", italics: true, color: GREY, size: 17 })] })
    ]
  }]
});

Packer.toBuffer(doc).then(b => { fs.writeFileSync("/home/claude/TLC_SOP_Standards.docx", b); console.log("written"); });

